def transform(wb):
    for ws in wb.worksheets:
        max_row = ws.max_row or 0
        for i in range(max_row, 0, -1):
            val = ws.cell(row=i, column=1).value
            if val is not None and str(val).strip() == 'Line No':
                if i + 1 <= ws.max_row:
                    below = ws.cell(row=i + 1, column=1).value
                else:
                    below = None
                if below is None or below == '':
                    if i + 1 <= ws.max_row:
                        ws.delete_rows(i, 2)
                    else:
                        ws.delete_rows(i, 1)
